    t_unlim[1] = -kp_eff * e_axis[1] - kd_eff * w_axis[1] - ki_eff * Iaxis_use[1];
    t_unlim[2] = -kp_eff * e_axis[2] - kd_eff * w_axis[2] - ki_eff * Iaxis_use[2];

    sat_mask = 0U;
    for (i = 0; i < 3; i++) {
        double limv = 0.0;
        (void)adcs_limit_scalar(t_unlim[i], &lim, &limv);
        t_lim[i] = limv;
        if (limv != t_unlim[i]) {
            sat_mask |= (uint32_t)(1U << i);
        }
    }

    ra_state.integral_error_rad_s = (adcs_vec3_t){Iaxis_use[0], Iaxis_use[1], Iaxis_use[2]};

    ra_output.mode = reached;
    ra_output.error_angle_rad = angle;
    ra_output.rate_magnitude_rad_s = rate_mag;
    ra_output.torque_nm = (adcs_vec3_t){t_lim[0], t_lim[1], t_lim[2]};
    ra_output.bad_samples = 0U;
    ra_output.saturation_mask = sat_mask;
    ra_state.bad_samples = 0U;

    return;
}

candidates.misra:
{
    int rejected = 0;
    int enabled = (ra_input.enable == 1) ? 1 : 0;
    ra_mode_t reached;
    adcs_quat_t qc, qt, qe;
    adcs_vec3_t e_rot, w;
    double angle = 0.0, rate_mag = 0.0;
    double kp_eff, kd_eff, ki_eff;
    adcs_vec3_t I_prev, I_prop;
    adcs_actuator_limit_t lim;
    double e_axis[3], w_axis[3], Iaxis_prev[3], Iaxis_prop[3], Iaxis_use[3];
    double t_unlim[3], t_lim[3];
    uint32_t sat_mask = 0U;
    int i;

    if ((ra_input.enable != 0) && (ra_input.enable != 1)) rejected = 1;
    if ((ra_input.valid != 0) && (ra_input.valid != 1)) rejected = 1;
    if (ra_input.valid == 0) rejected = 1;
    if ((ra_config.hold_enter_rad < 0.0) ||
        !(ra_config.hold_enter_rad < ra_config.hold_exit_rad) ||
        !(ra_config.hold_exit_rad <= ra_config.fine_enter_rad) ||
        !(ra_config.fine_enter_rad < ra_config.fine_exit_rad) ||
        !(ra_config.fine_exit_rad <= ADCS_PI)) rejected = 1;
    if ((ra_config.hold_rate_rad_s < 0.0) ||
        !(ra_config.hold_rate_rad_s < ra_config.hold_rate_exit_rad_s) ||
        !(ra_config.hold_rate_exit_rad_s <= ra_config.rate_enter_rad_s) ||
        !(ra_config.rate_enter_rad_s < ra_config.rate_exit_rad_s)) rejected = 1;
    if ((ra_config.rate_samples < 1U) || (ra_config.rate_samples > 20U)) rejected = 1;
    if ((ra_config.fine_samples < 1U) || (ra_config.fine_samples > 20U)) rejected = 1;
    if ((ra_config.hold_samples < 1U) || (ra_config.hold_samples > 20U)) rejected = 1;
    if ((ra_config.max_bad_samples < 1U) || (ra_config.max_bad_samples > 20U)) rejected = 1;
    if ((!isfinite(ra_config.dt_s)) || (ra_config.dt_s <= 0.0)) rejected = 1;
    if ((!isfinite(ra_config.integral_limit_rad_s)) || (ra_config.integral_limit_rad_s <= 0.0)) rejected = 1;
    if ((!isfinite(ra_config.torque_limit_nm)) || (ra_config.torque_limit_nm <= 0.0)) rejected = 1;
    if ((!isfinite(ra_config.kp)) || (ra_config.kp < 0.0)) rejected = 1;
    if ((!isfinite(ra_config.kd)) || (ra_config.kd < 0.0)) rejected = 1;
    if ((!isfinite(ra_config.ki)) || (ra_config.ki < 0.0)) rejected = 1;
    if ((ra_input.current_q_bi == NULL) || (ra_input.target_q_bi == NULL) ||
        (ra_input.body_rate_rad_s == NULL)) rejected = 1;
    if (!rejected) {
        if (!adcs_is_finite_vec3(ra_input.body_rate_rad_s)) rejected = 1;
    }
    if (!rejected) {
        if (adcs_quat_normalize(ra_input.current_q_bi, &qc) != ADCS_OK) rejected = 1;
    }
    if (!rejected) {
        if (adcs_quat_normalize(ra_input.target_q_bi, &qt) != ADCS_OK) rejected = 1;
    }

    if (rejected) {
        if (ra_state.bad_samples < ra_config.max_bad_samples) {
            ra_state.bad_samples++;
        }
        if (ra_state.bad_samples >= ra_config.max_bad_samples) {
            ra_state.mode = RA_FAULT;
        }
        ra_state.transition_samples = 0U;
        ra_state.integral_error_rad_s = (adcs_vec3_t){0, 0, 0};
        ra_output.mode = ra_state.mode;
        ra_output.error_angle_rad = 0.0;
        ra_output.rate_magnitude_rad_s = 0.0;
        ra_output.torque_nm = (adcs_vec3_t){0, 0, 0};
        ra_output.bad_samples = ra_state.bad_samples;
        ra_output.saturation_mask = 0U;
        return;
    }

    if (!enabled) {
        ra_state.mode = RA_OFF;
        ra_state.transition_samples = 0U;
        ra_state.bad_samples = 0U;
        ra_state.integral_error_rad_s = (adcs_vec3_t){0, 0, 0};
        ra_output.mode = RA_OFF;
        ra_output.error_angle_rad = 0.0;
        ra_output.rate_magnitude_rad_s = 0.0;
        ra_output.torque_nm = (adcs_vec3_t){0, 0, 0};
        ra_output.bad_samples = 0U;
        ra_output.saturation_mask = 0U;
        return;
    }

    {
        adcs_quat_t qc_conj = adcs_quat_conjugate(&qc);
        qe = adcs_quat_multiply(&qt, &qc_conj);
        if (qe.w < 0.0) {
            qe.w = -qe.w; qe.x = -qe.x; qe.y = -qe.y; qe.z = -qe.z;
        }
        {
            double s = sqrt(qe.x * qe.x + qe.y * qe.y + qe.z * qe.z);
            if (s <= ADCS_EPS_NORM) {
                e_rot = (adcs_vec3_t){0, 0, 0};
            } else {
                double ang = 2.0 * atan2(s, qe.w);
                adcs_vec3_t axis = {qe.x, qe.y, qe.z};
                e_rot = adcs_vec3_scale(&axis, ang / s);
            }
        }
    }
    w = *ra_input.body_rate_rad_s;
    angle = adcs_vec3_norm(&e_rot);
    rate_mag = adcs_vec3_norm(&w);

    if (ra_state.mode == RA_OFF) {
        ra_state.transition_samples = 0U;
        if (rate_mag > ra_config.rate_enter_rad_s) {
            ra_state.mode = RA_RATE_DAMP;
        } else {
            ra_state.mode = RA_COARSE;
        }
    } else if (ra_state.mode == RA_RATE_DAMP) {
        if (rate_mag >= ra_config.rate_exit_rad_s) {
            ra_state.transition_samples = 0U;
        } else if (rate_mag <= ra_config.rate_enter_rad_s) {
            if (ra_state.transition_samples < ra_config.rate_samples) {
                ra_state.transition_samples++;
            }
            if (ra_state.transition_samples >= ra_config.rate_samples) {
                ra_state.mode = RA_COARSE;
                ra_state.transition_samples = 0U;
            }
        } else {
            ra_state.transition_samples = 0U;
        }
    } else if (ra_state.mode == RA_COARSE) {
        if ((angle <= ra_config.fine_enter_rad) && (rate_mag <= ra_config.rate_enter_rad_s)) {
            if (ra_state.transition_samples < ra_config.fine_samples) {
                ra_state.transition_samples++;
            }
            if (ra_state.transition_samples >= ra_config.fine_samples) {
                ra_state.mode = RA_FINE;
                ra_state.transition_samples = 0U;
            }
        } else {
            ra_state.transition_samples = 0U;
        }
    } else if (ra_state.mode == RA_FINE) {
        if ((angle >= ra_config.fine_exit_rad) || (rate_mag >= ra_config.rate_exit_rad_s)) {
            ra_state.mode = RA_COARSE;
            ra_state.integral_error_rad_s = (adcs_vec3_t){0, 0, 0};
            ra_state.transition_samples = 0U;
        } else if ((angle <= ra_config.hold_enter_rad) && (rate_mag <= ra_config.hold_rate_rad_s)) {
            if (ra_state.transition_samples < ra_config.hold_samples) {
                ra_state.transition_samples++;
            }
            if (ra_state.transition_samples >= ra_config.hold_samples) {
                ra_state.mode = RA_HOLD;
                ra_state.transition_samples = 0U;
            }
        } else {
            ra_state.transition_samples = 0U;
        }
    } else if (ra_state.mode == RA_HOLD) {
        if ((angle >= ra_config.hold_exit_rad) || (rate_mag >= ra_config.hold_rate_exit_rad_s)) {
            ra_state.mode = RA_FINE;
            ra_state.transition_samples = 0U;
        }
    } else {
        ra_state.mode = RA_OFF;
        ra_state.transition_samples = 0U;
    }

    reached = ra_state.mode;

    kp_eff = ra_config.kp;
    kd_eff = ra_config.kd;
    ki_eff = ra_config.ki;
    if (reached == RA_RATE_DAMP) {
        kp_eff = 0.0;
        ki_eff = 0.0;
    } else if (reached == RA_COARSE) {
        ki_eff = 0.0;
    } else if ((reached == RA_FINE) || (reached == RA_HOLD)) {
        /* full PID */
    } else {
        kp_eff = 0.0; kd_eff = 0.0; ki_eff = 0.0;
    }

    I_prev = ra_state.integral_error_rad_s;
    I_prop = I_prev;
    if ((reached == RA_FINE) || (reached == RA_HOLD)) {
        I_prop.x = I_prev.x + e_rot.x * ra_config.dt_s;
        I_prop.y = I_prev.y + e_rot.y * ra_config.dt_s;
        I_prop.z = I_prev.z + e_rot.z * ra_config.dt_s;
        I_prop.x = ADCS_CLAMP(I_prop.x, -ra_config.integral_limit_rad_s, ra_config.integral_limit_rad_s);
        I_prop.y = ADCS_CLAMP(I_prop.y, -ra_config.integral_limit_rad_s, ra_config.integral_limit_rad_s);
        I_prop.z = ADCS_CLAMP(I_prop.z, -ra_config.integral_limit_rad_s, ra_config.integral_limit_rad_s);
    }

    lim.min_value = -ra_config.torque_limit_nm;
    lim.max_value = ra_config.torque_limit_nm;
    lim.max_slew_per_s = 0.0;

    e_axis[0] = e_rot.x; e_axis[1] = e_rot.y; e_axis[2] = e_rot.z;
    w_axis[0] = w.x; w_axis[1] = w.y; w_axis[2] = w.z;
    Iaxis_prev[0] = I_prev.x; Iaxis_prev[1] = I_prev.y; Iaxis_prev[2] = I_prev.z;
    Iaxis_prop[0] = I_prop.x; Iaxis_prop[1] = I_prop.y; Iaxis_prop[2] = I_prop.z;

    t_unlim[0] = -kp_eff * e_axis[0] - kd_eff * w_axis[0] - ki_eff * Iaxis_prop[0];
    t_unlim[1] = -kp_eff * e_axis[1] - kd_eff * w_axis[1] - ki_eff * Iaxis_prop[1];
    t_unlim[2] = -kp_eff * e_axis[2] - kd_eff * w_axis[2] - ki_eff * Iaxis_prop[2];

    for (i = 0; i < 3; i++) {
        double limv = 0.0;
        (void)adcs_limit_scalar(t_unlim[i], &lim, &limv);
        if (limv != t_unlim[i]) {
            sat_mask |= (uint32_t)(1U << i);
        }
    }

    for (i = 0; i < 3; i++) {
        Iaxis_use[i] = Iaxis_prop[i];
        if ((sat_mask & (uint32_t)(1U << i)) != 0U) {
            double dI = e_axis[i] * ra_config.dt_s;
            double dir_sat = (t_unlim[i] > 0.0) ? 1.0 : -1.0;
            double dir_ki_contrib = -ki_eff * dI;
            if (ki_eff > 0.0 && dir_sat * dir_ki_contrib > 0.0) {
                Iaxis_use[i] = Iaxis_prev[i];
            }
        }
    }

    t_unlim[0] = -kp_eff * e_axis[0] - kd_eff * w_axis[0] - ki_eff * Iaxis_use[0];
    t_unlim[1] = -kp_eff * e_axis[1] - kd_eff * w_axis[1] - ki_eff * Iaxis_use[1];
    t_unlim[2] = -kp_eff * e_axis[2] - kd_eff * w_axis[2] - ki_eff * Iaxis_use[2];

    sat_mask = 0U;
    for (i = 0; i < 3; i++) {
        double limv = 0.0;
        (void)adcs_limit_scalar(t_unlim[i], &lim, &limv);
        t_lim[i] = limv;
        if (limv != t_unlim[i]) {
            sat_mask |= (uint32_t)(1U << i);
        }
    }

    ra_state.integral_error_rad_s = (adcs_vec3_t){Iaxis_use[0], Iaxis_use[1], Iaxis_use[2]};

    ra_output.mode = reached;
    ra_output.error_angle_rad = angle;
    ra_output.rate_magnitude_rad_s = rate_mag;
    ra_output.torque_nm = (adcs_vec3_t){t_lim[0], t_lim[1], t_lim[2]};
    ra_output.bad_samples = 0U;
    ra_output.saturation_mask = sat_mask;
    ra_state.bad_samples = 0U;

    return;
}

candidates.raw:
{
    const double dt = ra_config.dt_s;
    int enable_ok, valid_ok, cfg_ok, ptr_ok, rate_finite_ok, quat_ok;
    adcs_quat_t qc, qt, qe;
    adcs_vec3_t e, w;
    double angle, rate;

    enable_ok = (ra_input.enable == 0 || ra_input.enable == 1);
    valid_ok  = (ra_input.valid  == 0 || ra_input.valid  == 1);
    ptr_ok = (ra_input.current_q_bi != NULL) && (ra_input.target_q_bi != NULL) &&
             (ra_input.body_rate_rad_s != NULL);
    rate_finite_ok = ptr_ok && adcs_is_finite_vec3(ra_input.body_rate_rad_s);

    cfg_ok = 1;
    cfg_ok = cfg_ok && isfinite(ra_config.hold_enter_rad) && isfinite(ra_config.hold_exit_rad) &&
             isfinite(ra_config.fine_enter_rad) && isfinite(ra_config.fine_exit_rad) &&
             isfinite(ra_config.hold_rate_rad_s) && isfinite(ra_config.hold_rate_exit_rad_s) &&
             isfinite(ra_config.rate_enter_rad_s) && isfinite(ra_config.rate_exit_rad_s);
    cfg_ok = cfg_ok && (ra_config.hold_enter_rad  >= 0.0);
    cfg_ok = cfg_ok && (ra_config.hold_enter_rad  <  ra_config.hold_exit_rad);
    cfg_ok = cfg_ok && (ra_config.hold_exit_rad   <= ra_config.fine_enter_rad);
    cfg_ok = cfg_ok && (ra_config.fine_enter_rad  <  ra_config.fine_exit_rad);
    cfg_ok = cfg_ok && (ra_config.fine_exit_rad   <= ADCS_PI);
    cfg_ok = cfg_ok && (ra_config.hold_rate_rad_s >= 0.0);
    cfg_ok = cfg_ok && (ra_config.hold_rate_rad_s < ra_config.hold_rate_exit_rad_s);
    cfg_ok = cfg_ok && (ra_config.hold_rate_exit_rad_s <= ra_config.rate_enter_rad_s);
    cfg_ok = cfg_ok && (ra_config.rate_enter_rad_s < ra_config.rate_exit_rad_s);
    cfg_ok = cfg_ok && (ra_config.rate_samples >= 1U) && (ra_config.rate_samples <= 20U);
    cfg_ok = cfg_ok && (ra_config.fine_samples >= 1U) && (ra_config.fine_samples <= 20U);
    cfg_ok = cfg_ok && (ra_config.hold_samples >= 1U) && (ra_config.hold_samples <= 20U);
    cfg_ok = cfg_ok && (ra_config.max_bad_samples >= 1U) && (ra_config.max_bad_samples <= 20U);
    cfg_ok = cfg_ok && isfinite(ra_config.dt_s) && (ra_config.dt_s > 0.0);
    cfg_ok = cfg_ok && isfinite(ra_config.integral_limit_rad_s) &&
             (ra_config.integral_limit_rad_s > 0.0);
    cfg_ok = cfg_ok && isfinite(ra_config.torque_limit_nm) && (ra_config.torque_limit_nm > 0.0);
    cfg_ok = cfg_ok && isfinite(ra_config.kp) && (ra_config.kp >= 0.0);
    cfg_ok = cfg_ok && isfinite(ra_config.kd) && (ra_config.kd >= 0.0);
    cfg_ok = cfg_ok && isfinite(ra_config.ki) && (ra_config.ki >= 0.0);

    quat_ok = ptr_ok &&
              (adcs_quat_normalize(ra_input.current_q_bi, &qc) == ADCS_OK) &&
              (adcs_quat_normalize(ra_input.target_q_bi,  &qt) == ADCS_OK);

    if ((!enable_ok) || (!valid_ok) || (!ptr_ok) || (!rate_finite_ok) ||
        (ra_input.valid == 0) || (!cfg_ok) || (!quat_ok)) {
        adcs_vec3_t zero = {0.0, 0.0, 0.0};
        double ang = 0.0, rmag = 0.0;
        ra_state.transition_samples = 0U;
        ra_state.integral_error_rad_s = zero;
        if (ra_state.mode != RA_FAULT) {
            ra_state.bad_samples += 1U;
            if (ra_state.bad_samples >= ra_config.max_bad_samples) {
                ra_state.mode = RA_FAULT;
            }
        }
        ra_output.mode = ra_state.mode;
        ra_output.bad_samples = ra_state.bad_samples;
        ra_output.torque_nm = zero;
        ra_output.saturation_mask = 0U;
        if (quat_ok && rate_finite_ok) {
            adcs_quat_t conj2, qe2;
            adcs_vec3_t e2, w2;
            conj2 = adcs_quat_conjugate(&qc);
            qe2 = adcs_quat_multiply(&qt, &conj2);
            if (qe2.w < 0.0) { qe2.w = -qe2.w; qe2.x = -qe2.x; qe2.y = -qe2.y; qe2.z = -qe2.z; }
            e2.x = qe2.x; e2.y = qe2.y; e2.z = qe2.z;
            ang = 2.0 * atan2(adcs_vec3_norm(&e2), qe2.w);
            w2 = *ra_input.body_rate_rad_s;
            rmag = adcs_vec3_norm(&w2);
        }
        ra_output.error_angle_rad = ang;
        ra_output.rate_magnitude_rad_s = rmag;
        return;
    }

    ra_state.bad_samples = 0U;

    if (!ra_input.enable) {
        adcs_vec3_t zero = {0.0, 0.0, 0.0};
        ra_state.mode = RA_OFF;
        ra_state.transition_samples = 0U;
        ra_state.integral_error_rad_s = zero;
        ra_output.mode = RA_OFF;
        ra_output.error_angle_rad = 0.0;
        ra_output.rate_magnitude_rad_s = 0.0;
        ra_output.torque_nm = zero;
        ra_output.saturation_mask = 0U;
        ra_output.bad_samples = 0U;
        return;
    }

    {
        adcs_quat_t conj = adcs_quat_conjugate(&qc);
        qe = adcs_quat_multiply(&qt, &conj);
        if (qe.w < 0.0) { qe.w = -qe.w; qe.x = -qe.x; qe.y = -qe.y; qe.z = -qe.z; }
        e.x = qe.x; e.y = qe.y; e.z = qe.z;
        angle = 2.0 * atan2(adcs_vec3_norm(&e), qe.w);
    }
    w = *ra_input.body_rate_rad_s;
    rate = adcs_vec3_norm(&w);

    switch (ra_state.mode) {
    case RA_OFF:
        ra_state.transition_samples = 0U;
        if (rate > ra_config.rate_enter_rad_s) ra_state.mode = RA_RATE_DAMP;
        else ra_state.mode = RA_COARSE;
        break;
    case RA_RATE_DAMP:
        if (rate >= ra_config.rate_exit_rad_s) {
            ra_state.transition_samples = 0U;
        } else if (rate <= ra_config.rate_enter_rad_s) {
            ra_state.transition_samples += 1U;
            if (ra_state.transition_samples >= ra_config.rate_samples) {
                ra_state.transition_samples = 0U;
                ra_state.mode = RA_COARSE;
            }
        } else {
            ra_state.transition_samples = 0U;
        }
        break;
    case RA_COARSE:
        if ((angle <= ra_config.fine_enter_rad) && (rate <= ra_config.rate_enter_rad_s)) {
            ra_state.transition_samples += 1U;
            if (ra_state.transition_samples >= ra_config.fine_samples) {
                ra_state.transition_samples = 0U;
                ra_state.mode = RA_FINE;
            }
        } else {
            ra_state.transition_samples = 0U;
        }
        break;
    case RA_FINE:
        if ((angle >= ra_config.fine_exit_rad) || (rate >= ra_config.rate_exit_rad_s)) {
            ra_state.mode = RA_COARSE;
            ra_state.integral_error_rad_s = (adcs_vec3_t){0.0, 0.0, 0.0};
            ra_state.transition_samples = 0U;
        } else if ((angle <= ra_config.hold_enter_rad) && (rate <= ra_config.hold_rate_rad_s)) {
            ra_state.transition_samples += 1U;
            if (ra_state.transition_samples >= ra_config.hold_samples) {
                ra_state.transition_samples = 0U;
                ra_state.mode = RA_HOLD;
            }
        } else {
            ra_state.transition_samples = 0U;
        }
        break;
    case RA_HOLD:
        if ((angle >= ra_config.hold_exit_rad) || (rate >= ra_config.hold_rate_exit_rad_s)) {
            ra_state.mode = RA_FINE;
            ra_state.transition_samples = 0U;
        }
        break;
    case RA_FAULT:
    default:
        break;
    }

    {
        double kp_use = ra_config.kp;
        double kd_use = ra_config.kd;
        double ki_use = ra_config.ki;
        adcs_vec3_t I_prev = ra_state.integral_error_rad_s;
        adcs_vec3_t I_prop, I_use;
        adcs_vec3_t t_cmd;
        double ev[3], wv[3], ip[3], iv[3], tu[3], tc[3];
        double tmax_abs = ra_config.torque_limit_nm;
        unint32 mask = 0U;
        adcs_actuator_limit_t lim;
        int i;

        switch (ra_state.mode) {
        case RA_RATE_DAMP: kp_use = 0.0; ki_use = 0.0; break;
        case RA_COARSE:    ki_use = 0.0; break;
        default: break;
        }

        I_prop.x = ADCS_CLAMP(I_prev.x + e.x * dt, -ra_config.integral_limit_rad_s, ra_config.integral_limit_rad_s);
        I_prop.y = ADCS_CLAMP(I_prev.y + e.y * dt, -ra_config.integral_limit_rad_s, ra_config.integral_limit_rad_s);
        I_prop.z = ADCS_CLAMP(I_prev.z + e.z * dt, -ra_config.integral_limit_rad_s, ra_config.integral_limit_rad_s);

        ev[0] = e.x; ev[1] = e.y; ev[2] = e.z;
        wv[0] = w.x; wv[1] = w.y; wv[2] = w.z;
        ip[0] = I_prop.x; ip[1] = I_prop.y; ip[2] = I_prop.z;

        for (i = 0; i < 3; i++) {
            iv[i] = ip[i];
        }

        lim.min_value = -ra_config.torque_limit_nm;
