        I_prop.y = ADCS_CLAMP(I_prev.y + e.y * dt, -ra_config.integral_limit_rad_s, ra_config.integral_limit_rad_s);
        I_prop.z = ADCS_CLAMP(I_prev.z + e.z * dt, -ra_config.integral_limit_rad_s, ra_config.integral_limit_rad_s);

        ev[0] = e.x; ev[1] = e.y; ev[2] = e.z;
        wv[0] = w.x; wv[1] = w.y; wv[2] = w.z;
        ip[0] = I_prop.x; ip[1] = I_prop.y; ip[2] = I_prop.z;

        for (i = 0; i < 3; i++) {
