        lim.min_value = -ra_config.torque_limit_nm;
        lim.max_value =  ra_config.torque_limit_nm;
        lim.max_slew_per_s = 0.0;

        /* Probe unlimited torque using proposed integral. */
        for (i = 0; i < 3; i++) {
            tu[i] = -kp_use * ev[i] - kd_use * wv[i] - ki_use * ip[i];
        }
        /* Freeze axis where proposed update would drive already-saturated torque deeper. */
        {
            double prev[3];
            prev[0] = I_prev.x; prev[1] = I_prev.y; prev[2] = I_prev.z;
            for (i = 0; i < 3; i++) {
                int saturated = (tu[i] > tmax_abs) || (tu[i] < -tmax_abs);
