                    if ((tu[i] > tmax_abs) && (ip[i] > prev[i])) {
                        iv[i] = prev[i];
                    } else if ((tu[i] < -tmax_abs) && (ip[i] < prev[i])) {
                        iv[i] = prev[i];
                    } else {
                        iv[i] = ip[i];
                    }
                } else {
                    iv[i] = ip[i];
                }
            }
        }
        /* Final torque with used integral. */
        for (i = 0; i < 3; i++) {
            tu[i] = -kp_use * ev[i] - kd_use * wv[i] - ki_use * iv[i];
        }
        for (i = 0; i < 3; i++) {
            uint32_t bit = (uint32_t)(1U << (uint32_t)i);
            if (tu[i] > tmax_abs) { tc[i] = tmax_abs; mask = mask | bit; }
            else if (tu[i] < -tmax_abs) { tc[i] = -tmax_abs; mask = mask | bit; }
            else { tc[i] = tu[i]; }
        }

        I_use.x = iv[0]; I_use.y = iv[1]; I_use.z = iv[2];
        ra_state.integral_error_rad_s = I_use;
        t_cmd.x = tc[0]; t_cmd.y = tc[1]; t_cmd.z = tc[2];
        ra_output.torque_nm = t_cmd;
        ra_output.saturation_mask = mask;
    }

    ra_output.mode = ra_state.mode;
    ra_output.error_angle_rad = angle;
    ra_output.rate_magnitude_rad_s = rate;
    ra_output.bad_samples = ra_state.bad_samples;
}

