                }
            }
        }
        ra_state.integral_error_rad_s.x = prop_i[0];
        ra_state.integral_error_rad_s.y = prop_i[1];
        ra_state.integral_error_rad_s.z = prop_i[2];
    } else {
        ra_state.integral_error_rad_s = (adcs_vec3_t){0, 0, 0};
    }

    ra_state.mode = next_mode;
    ra_state.bad_samples = 0U;

    ra_output.mode = next_mode;
    ra_output.error_angle_rad = angle;
    ra_output.rate_magnitude_rad_s = rate_mag;
    ra_output.torque_nm.x = torq[0];
    ra_output.torque_nm.y = torq[1];
    ra_output.torque_nm.z = torq[2];
    ra_output.bad_samples = ra_state.bad_samples;
    ra_output.saturation_mask = sat_mask;
}

