        if (raw_torq[i] > ra_config.torque_limit_nm) sat_mask |= (uint32_t)(1U << i);
        if (raw_torq[i] < -ra_config.torque_limit_nm) sat_mask |= (uint32_t)(1U << i);
    }

    if ((next_mode == RA_FINE) || (next_mode == RA_HOLD)) {
        for (i = 0U; i < 3U; i++) {
            int sat_pos = (raw_torq[i] > ra_config.torque_limit_nm);
            int sat_neg = (raw_torq[i] < -ra_config.torque_limit_nm);
            if (sat_pos || sat_neg) {
                double delta = prop_i[i] - i_axis[i];
                if ((sat_pos && (delta > 0.0)) || (sat_neg && (delta < 0.0))) {
                    prop_i[i] = i_axis[i];
                    torq[i] = -kp_use * e_axis[i] - kd_use * w_axis[i] - ki_use * i_axis[i];
                    torq[i] = ADCS_CLAMP(torq[i], -ra_config.torque_limit_nm, ra_config.torque_limit_nm);
                }
            }
        }
        ra_state.integral_error_rad_s.x = prop_i[0];
        ra_state.integral_error_rad_s.y = prop_i[1];
        ra_state.integral_error_rad_s.z = prop_i[2];
    } else {
        ra_state.integral_error_rad_s = (adcs_vec3_t){0, 0, 0};
    }

    ra_state.mode = next_mode;
    ra_state.bad_samples = 0U;

    ra_output.mode = next_mode;
    ra_output.error_angle_rad = angle;
    ra_output.rate_magnitude_rad_s = rate_mag;
    ra_output.torque_nm.x = torq[0];
    ra_output.torque_nm.y = torq[1];
    ra_output.torque_nm.z = torq[2];
    ra_output.bad_samples = ra_state.bad_samples;
    ra_output.saturation_mask = sat_mask;
}

candidates.misra:
{
    const adcs_quat_t *cq = ra_input.current_q_bi;
    const adcs_quat_t *tq = ra_input.target_q_bi;
    const adcs_vec3_t *w = ra_input.body_rate_rad_s;
    adcs_quat_t qc, qt, qerr, qc_conj;
    adcs_vec3_t e, rate;
    double angle, rate_mag, dt, kp_use, kd_use, ki_use;
    double e_axis[3], w_axis[3], i_axis[3], prop_i[3], torq[3], raw_torq[3];
    uint32_t sat_mask = 0U, i;
    int reject = 0;
    adcs_actuator_limit_t lim;
    double limv;
    ra_mode_t next_mode;
    int valid_cfg;

    valid_cfg = (int)((ra_config.hold_enter_rad >= 0.0) &&
                (ra_config.hold_enter_rad < ra_config.hold_exit_rad) &&
                (ra_config.hold_exit_rad <= ra_config.fine_enter_rad) &&
                (ra_config.fine_enter_rad < ra_config.fine_exit_rad) &&
                (ra_config.fine_exit_rad <= ADCS_PI) &&
                (ra_config.hold_rate_rad_s >= 0.0) &&
                (ra_config.hold_rate_rad_s < ra_config.hold_rate_exit_rad_s) &&
                (ra_config.hold_rate_exit_rad_s <= ra_config.rate_enter_rad_s) &&
                (ra_config.rate_enter_rad_s < ra_config.rate_exit_rad_s) &&
                (ra_config.rate_samples >= 1U) && (ra_config.rate_samples <= 20U) &&
                (ra_config.fine_samples >= 1U) && (ra_config.fine_samples <= 20U) &&
                (ra_config.hold_samples >= 1U) && (ra_config.hold_samples <= 20U) &&
                (ra_config.max_bad_samples >= 1U) && (ra_config.max_bad_samples <= 20U) &&
                isfinite(ra_config.dt_s) && (ra_config.dt_s > 0.0) &&
                isfinite(ra_config.integral_limit_rad_s) && (ra_config.integral_limit_rad_s > 0.0) &&
                isfinite(ra_config.torque_limit_nm) && (ra_config.torque_limit_nm > 0.0) &&
                isfinite(ra_config.kp) && (ra_config.kp >= 0.0) &&
                isfinite(ra_config.kd) && (ra_config.kd >= 0.0) &&
                isfinite(ra_config.ki) && (ra_config.ki >= 0.0));

    if ((ra_input.enable != 0) && (ra_input.enable != 1)) reject = 1;
    if ((ra_input.valid != 0) && (ra_input.valid != 1)) reject = 1;
    if (!valid_cfg) reject = 1;
    if (ra_input.enable == 0) {
        ra_state.mode = RA_OFF;
        ra_state.transition_samples = 0U;
        ra_state.bad_samples = 0U;
        ra_state.integral_error_rad_s = (adcs_vec3_t){0, 0, 0};
        ra_output.mode = RA_OFF;
        ra_output.error_angle_rad = 0.0;
        ra_output.rate_magnitude_rad_s = 0.0;
        ra_output.torque_nm = (adcs_vec3_t){0, 0, 0};
        ra_output.bad_samples = 0U;
        ra_output.saturation_mask = 0U;
        return;
    }
    if (ra_input.valid == 0) reject = 1;
    if ((cq == NULL) || (tq == NULL) || (w == NULL)) reject = 1;
    if ((!reject) && (!adcs_is_finite_vec3(w))) reject = 1;
    if (!reject) {
        if ((adcs_quat_normalize(cq, &qc) != ADCS_OK) ||
            (adcs_quat_normalize(tq, &qt) != ADCS_OK)) reject = 1;
    }
    if (reject) {
        if (ra_state.mode != RA_FAULT) {
            ra_state.transition_samples = 0U;
            ra_state.integral_error_rad_s = (adcs_vec3_t){0, 0, 0};
            ra_state.bad_samples += 1U;
            if (ra_state.bad_samples >= ra_config.max_bad_samples) {
                ra_state.bad_samples = ra_config.max_bad_samples;
                ra_state.mode = RA_FAULT;
            }
        }
        ra_output.mode = ra_state.mode;
        ra_output.error_angle_rad = 0.0;
        ra_output.rate_magnitude_rad_s = 0.0;
        ra_output.torque_nm = (adcs_vec3_t){0, 0, 0};
        ra_output.bad_samples = ra_state.bad_samples;
        ra_output.saturation_mask = 0U;
        return;
    }

    qc_conj = adcs_quat_conjugate(&qc);
    qerr = adcs_quat_multiply(&qt, &qc_conj);
    if (qerr.w < 0.0) {
        qerr.w = -qerr.w; qerr.x = -qerr.x; qerr.y = -qerr.y; qerr.z = -qerr.z;
    }
    {
        double qn = sqrt(qerr.x * qerr.x + qerr.y * qerr.y + qerr.z * qerr.z);
        angle = 2.0 * atan2(qn, qerr.w);
        if (qn > 1.0e-12) {
            double f = angle / qn;
            e.x = f * qerr.x; e.y = f * qerr.y; e.z = f * qerr.z;
        } else {
            e.x = 0.0; e.y = 0.0; e.z = 0.0;
        }
    }
    rate = *w;
    rate_mag = sqrt(rate.x * rate.x + rate.y * rate.y + rate.z * rate.z);

    next_mode = ra_state.mode;
    switch (ra_state.mode) {
    case RA_OFF:
        if (rate_mag > ra_config.rate_enter_rad_s) {
            next_mode = RA_RATE_DAMP;
            ra_state.transition_samples = 0U;
        } else {
            next_mode = RA_COARSE;
            ra_state.transition_samples = 0U;
        }
        break;
    case RA_RATE_DAMP:
        if (rate_mag >= ra_config.rate_exit_rad_s) {
            ra_state.transition_samples = 0U;
        } else if (rate_mag <= ra_config.rate_enter_rad_s) {
            ra_state.transition_samples++;
            if (ra_state.transition_samples >= ra_config.rate_samples) {
                next_mode = RA_COARSE;
                ra_state.transition_samples = 0U;
            }
        } else {
            ra_state.transition_samples = 0U;
        }
        break;
    case RA_COARSE:
        if ((angle <= ra_config.fine_enter_rad) && (rate_mag <= ra_config.rate_enter_rad_s)) {
            ra_state.transition_samples++;
            if (ra_state.transition_samples >= ra_config.fine_samples) {
                next_mode = RA_FINE;
                ra_state.transition_samples = 0U;
            }
        } else {
            ra_state.transition_samples = 0U;
        }
        break;
    case RA_FINE:
        if ((angle >= ra_config.fine_exit_rad) || (rate_mag >= ra_config.rate_exit_rad_s)) {
            next_mode = RA_COARSE;
            ra_state.transition_samples = 0U;
            ra_state.integral_error_rad_s = (adcs_vec3_t){0, 0, 0};
        } else if ((angle <= ra_config.hold_enter_rad) &&
                   (rate_mag <= ra_config.hold_rate_rad_s)) {
            ra_state.transition_samples++;
            if (ra_state.transition_samples >= ra_config.hold_samples) {
                next_mode = RA_HOLD;
                ra_state.transition_samples = 0U;
            }
        } else {
            ra_state.transition_samples = 0U;
        }
        break;
    case RA_HOLD:
        if ((angle >= ra_config.hold_exit_rad) ||
            (rate_mag >= ra_config.hold_rate_exit_rad_s)) {
            next_mode = RA_FINE;
            ra_state.transition_samples = 0U;
        }
        break;
    default:
        break;
    }

    dt = ra_config.dt_s;
    e_axis[0] = e.x; e_axis[1] = e.y; e_axis[2] = e.z;
    w_axis[0] = rate.x; w_axis[1] = rate.y; w_axis[2] = rate.z;
    i_axis[0] = ra_state.integral_error_rad_s.x;
    i_axis[1] = ra_state.integral_error_rad_s.y;
    i_axis[2] = ra_state.integral_error_rad_s.z;

    kp_use = ra_config.kp; kd_use = ra_config.kd; ki_use = ra_config.ki;
    if (next_mode == RA_RATE_DAMP) {
        kp_use = 0.0; ki_use = 0.0; kd_use = ra_config.kd;
    } else if (next_mode == RA_COARSE) {
        ki_use = 0.0; kp_use = ra_config.kp; kd_use = ra_config.kd;
    } else if ((next_mode == RA_FINE) || (next_mode == RA_HOLD)) {
        kp_use = ra_config.kp; kd_use = ra_config.kd; ki_use = ra_config.ki;
    } else {
        kp_use = 0.0; kd_use = 0.0; ki_use = 0.0;
    }

    for (i = 0U; i < 3U; i++) {
        double pi = i_axis[i];
        if ((next_mode == RA_FINE) || (next_mode == RA_HOLD)) {
            pi = i_axis[i] + e_axis[i] * dt;
            pi = ADCS_CLAMP(pi, -ra_config.integral_limit_rad_s, ra_config.integral_limit_rad_s);
        }
        prop_i[i] = pi;
        raw_torq[i] = -kp_use * e_axis[i] - kd_use * w_axis[i] - ki_use * pi;
    }

    lim.min_value = -ra_config.torque_limit_nm;
    lim.max_value = ra_config.torque_limit_nm;
    lim.max_slew_per_s = 0.0;
    for (i = 0U; i < 3U; i++) {
        if (adcs_limit_scalar(raw_torq[i], &lim, &limv) != ADCS_OK) limv = 0.0;
        torq[i] = limv;
        if (raw_torq[i] > ra_config.torque_limit_nm) sat_mask |= (uint32_t)(1U << i);
        if (raw_torq[i] < -ra_config.torque_limit_nm) sat_mask |= (uint32_t)(1U << i);
    }

    if ((next_mode == RA_FINE) || (next_mode == RA_HOLD)) {
        for (i = 0U; i < 3U; i++) {
            int sat_pos = (raw_torq[i] > ra_config.torque_limit_nm) ? 1 : 0;
            int sat_neg = (raw_torq[i] < -ra_config.torque_limit_nm) ? 1 : 0;
            if (sat_pos || sat_neg) {
                double delta = prop_i[i] - i_axis[i];
                if ((sat_pos && (delta > 0.0)) || (sat_neg && (delta < 0.0))) {
                    prop_i[i] = i_axis[i];
                    torq[i] = -kp_use * e_axis[i] - kd_use * w_axis[i] - ki_use * i_axis[i];
                    torq[i] = ADCS_CLAMP(torq[i], -ra_config.torque_limit_nm, ra_config.torque_limit_nm);
                }
            }
        }
        ra_state.integral_error_rad_s.x = prop_i[0];
        ra_state.integral_error_rad_s.y = prop_i[1];
        ra_state.integral_error_rad_s.z = prop_i[2];
    } else {
        ra_state.integral_error_rad_s = (adcs_vec3_t){0, 0, 0};
    }

    ra_state.mode = next_mode;
    ra_state.bad_samples = 0U;

    ra_output.mode = next_mode;
    ra_output.error_angle_rad = angle;
    ra_output.rate_magnitude_rad_s = rate_mag;
    ra_output.torque_nm.x = torq[0];
    ra_output.torque_nm.y = torq[1];
    ra_output.torque_nm.z = torq[2];
    ra_output.bad_samples = ra_state.bad_samples;
    ra_output.saturation_mask = sat_mask;
}
